from pydantic import BaseModel, validator


class User(BaseModel):
    name: str
    email: str

    @validator("email")
    def email_must_have_at(cls, v):
        if "@" not in v:
            raise ValueError("invalid email")
        return v


def serialize(user):
    return user.dict()

